def solve(grid):
    """Return the number of islands in a grid of 0s and 1s.
    Islands are groups of adjacent (up, down, left, right) 1s.
    The grid may be non‑rectangular (rows can have different lengths).
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited mirrors the shape of grid
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore four directions
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows:
                    if 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                        stack.append((nx, ny))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

