def solve(nums):
    """Return length of longest strictly increasing subsequence in nums.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
}

